using Atm;
class Spy(MoneyDispenser inner) : IMoneyDispenser {
  public List<string> Log = new();
  public NoteCounts Stock => inner.Stock; public Denomination? Jammed => inner.Jammed;
  public bool Dispense(NoteCounts n){ var r=inner.Dispense(n); Log.Add($"D({n.Fifties},{n.Twenties},{n.Tens})={r}"); return r;}
  public bool Load(NoteCounts n){ var r=inner.Load(n); Log.Add($"L({n.Fifties},{n.Twenties},{n.Tens})={r}"); return r;}
}
static class P { static void Main(){
  foreach (var (s,a) in new[]{((0,5,0),100),((0,1,4),60),((3,5,0),190),((0,5,5),150),((2,3,4),150),((0,0,5),50),((5,5,5),90),((1,5,5),200),((0,2,3),70)}) {
    var spy=new Spy(new MoneyDispenser(new NoteCounts(s.Item1,s.Item2,s.Item3)));
    var r=new CashMachine(spy).Execute(new AccountState(250,0), new Operation.Withdraw(a));
    Console.WriteLine($"{s} {a}: {r.Status} notes=({r.Notes.Fifties},{r.Notes.Twenties},{r.Notes.Tens}) {string.Join(" ",spy.Log)}");
  }
}}
